const searchInput = document.querySelector('#searchBox');
const bookListContainer = document.querySelector('#booksContainer');

function filterAndRenderBooks(query, books) {
    const normalizedQuery = query.toLowerCase().trim();
    const filtered = books.filter(book => 
        book.title.toLowerCase().includes(normalizedQuery)
    );

    bookListContainer.innerHTML = '';
    filtered.forEach(book => {
        const card = document.createElement('div');
        card.className = 'book-card';
        card.textContent = `${book.title} (автор: ${book.author})`;
        bookListContainer.appendChild(card);
    });
}

searchInput.addEventListener('input', (event) => {
    filterAndRenderBooks(event.target.value, catalogData);
});
]

4.1. Етапи, база та методика проведення педагогічного експерименту

Для перевірки висунутої науково-методичної гіпотези щодо ефективності розробленої методичної системи формування алгоритмічної компетентності старшокласників засобами платформи Smart-BKT-Chain було організовано та проведено педагогічний експеримент. Дослідно-експериментальна робота здійснювалася протягом 2025–2026 навчального року на базі ліцеїв та закладів загальної середньої освіти.

Загальна вибірка дослідження охопила 112 учнів 10–11 класів, які вивчали курс інформатики на рівні стандарту та профільному рівні. Для забезпечення коректності та валідності результатів учнів було розподілено на дві репрезентативні групи:
- Контрольна група (КГ, n_1 = 56 учнів): навчання розділу «Вебтехнології» здійснювалося за традиційною методикою з фронтальним поясненням матеріалу та виконанням статичних завдань у локальних текстових редакторах без адаптивної підтримки;
- Експериментальна група (ЕГ, n_2 = 56 учнів): навчальний процес організовувався на базі розробленої методики з використанням платформи Smart-BKT-Chain, дидактичного рушія Zen Focus, адаптивного підказування Scaffolding та теплових карт моніторингу знань.

Педагогічний експеримент складався з трьох послідовних взаємопов'язаних етапів:
1. Констатувальний етап: діагностика вихідного рівня алгоритмічної підготовки учнів контрольної та експериментальної груп, анкетування щодо пізнавального інтересу до веб-програмування;
2. Формувальний етап: практичне впровадження розробленого навчально-методичного комплексу та платформи Smart-BKT-Chain в освітній процес експериментальної групи протягом 18 навчальних годин;
3. Контрольний етап: підсумковий контрольний зріз, математично-статистична обробка результатів та оцінка достовірності зрушень.
